#!/usr/bin/env python3
"""Naive reference engine (testing only, not submitted)."""
import json


class RefError(Exception):
    pass


class Ref:
    def __init__(self, cfg):
        self.it = cfg["idle_timeout"]
        self.pl = cfg["packet_limit"]
        self.W = cfg["prefix_width"]
        self.rules = sorted(cfg["rules"], key=lambda r: r["id"])
        self.fb = cfg["fallback"]
        self.flows = {}
        self.time = 0

    # ---- helpers
    def fbclass(self, feats):
        pad = list(feats[: self.W]) + [0] * (self.W - len(feats))
        nd = self.fb
        while "feature" in nd:
            nd = nd["le"] if pad[nd["feature"]] <= nd["threshold"] else nd["gt"]
        return nd["class"]

    def advance(self, T, events):
        if T < self.time:
            raise RefError("time")
        self.time = T
        thr = T - self.it
        exp = sorted(fid for fid, f in self.flows.items()
                     if f["dec"] is None and f["lat"] < thr)
        for fid in exp:
            f = self.flows[fid]
            cls = self.fbclass(f["feats"])
            f["dec"] = ("idle", cls, None)
            events.append({"type": "decision", "flow": fid, "class": cls,
                           "reason": "idle", "at": f["n"], "time": T,
                           "rule": None})

    def open(self, fid, T, events):
        self.advance(T, events)
        if fid in self.flows:
            raise RefError("dup open")
        if len(self.flows) >= 4096:
            raise RefError("too many")
        self.flows[fid] = {"n": 0, "m": 0, "dec": None, "lat": T,
                           "dir": None, "feats": []}

    def tick(self, T, events):
        self.advance(T, events)

    def packet(self, fid, T, src, ln, events):
        self.advance(T, events)
        f = self.flows.get(fid)
        if f is None:
            raise RefError("absent")
        if f["dir"] is None:
            f["dir"] = src
            c = ln
        else:
            c = ln if src == f["dir"] else -ln
        f["n"] += 1
        n = f["n"]
        f["lat"] = T
        f["feats"].append(c)
        matches = []
        for r in self.rules:
            k = len(r["ranges"])
            if k > n:
                continue
            ok = True
            for i, (lo, hi) in enumerate(r["ranges"]):
                v = f["feats"][n - k + i]
                if v < lo or v > hi:
                    ok = False
                    break
            if ok:
                matches.append(r)
        for r in matches:
            k = len(r["ranges"])
            events.append({"type": "match", "flow": fid, "rule": r["id"],
                           "start": n - k, "end": n})
            f["m"] += 1
        if f["dec"] is None and matches:
            best = max(matches, key=lambda r: (r["priority"], len(r["ranges"]), -r["id"]))
            f["dec"] = ("key", best["class"], best["id"])
            events.append({"type": "decision", "flow": fid,
                           "class": best["class"], "reason": "key",
                           "at": n, "time": T, "rule": best["id"]})
        elif f["dec"] is None and n >= self.pl:
            cls = self.fbclass(f["feats"])
            f["dec"] = ("packet_limit", cls, None)
            events.append({"type": "decision", "flow": fid, "class": cls,
                           "reason": "packet_limit", "at": n, "time": T,
                           "rule": None})

    def close(self, fid, T, events):
        self.advance(T, events)
        f = self.flows.get(fid)
        if f is None:
            raise RefError("absent")
        if f["dec"] is None:
            cls = self.fbclass(f["feats"])
            f["dec"] = ("end", cls, None)
            events.append({"type": "decision", "flow": fid, "class": cls,
                           "reason": "end", "at": f["n"], "time": T,
                           "rule": None})
        reason, cls, rid = f["dec"]
        events.append({"type": "closed", "flow": fid, "packets": f["n"],
                       "matches": f["m"], "class": cls, "reason": reason,
                       "rule": rid})
        del self.flows[fid]

    # ---- checkpoint: keep everything, plainly
    def checkpoint(self):
        return {"t": self.time,
                "f": [[fid, f["n"], f["m"], f["lat"], f["dir"], list(f["feats"]),
                       f["dec"]] for fid, f in sorted(self.flows.items())]}

    def restore(self, val):
        self.time = val["t"]
        self.flows = {}
        for fid, n, m, lat, d, feats, dec in val["f"]:
            self.flows[fid] = {"n": n, "m": m, "dec": None if dec is None else tuple(dec),
                               "lat": lat, "dir": d, "feats": feats}

    def request(self, req, first=False):
        events = []
        op = req.get("op")
        if op == "open":
            self.open(req["flow"], req["time"], events)
        elif op == "tick":
            self.tick(req["time"], events)
        elif op == "chunk":
            for p in req["packets"]:
                self.packet(p["flow"], p["time"], p["source"], p["length"], events)
        elif op == "close":
            self.close(req["flow"], req["time"], events)
        elif op == "checkpoint":
            return {"checkpoint": self.checkpoint()}
        elif op == "restore":
            if not first:
                raise RefError("restore late")
            self.restore(req["checkpoint"])
        else:
            raise RefError("op")
        return {"events": events}
PYEOF
